71	// Cooperatively stage the per-element meta-net phi weights into shared memory
72	// ONCE per block, then hand the shared pointers to the canonical
73	// sg11_phi_forward<H>. W1 is [H,2] (row-major, 2 inputs/hidden unit), b1/W2 are
74	// [H]. The same weights are read by every element this block processes; staging
75	// removes the per-element re-read from GLOBAL inside the H-wide forward loop. NO
76	// math/signature change — the fn still takes const float* (single-sourced in
77	// algorithms/supergrok11.h).
78	template <int H>
79	__device__ __forceinline__ void sg11_stage_phi_weights(
80	    const float* __restrict__ W1, const float* __restrict__ b1,
81	    const float* __restrict__ W2,
82	    float* sW1, float* sb1, float* sW2
83	) {
84	    for (int j = threadIdx.x; j < H * 2; j += blockDim.x) sW1[j] = W1[j];
85	    for (int j = threadIdx.x; j < H;     j += blockDim.x) { sb1[j] = b1[j]; sW2[j] = W2[j]; }
86	    __syncthreads();
87	}
