234	// Sharpness restore: param = backup, sharpness = ||sam_grad - normal_grad||
235	template <typename ParamT>
236	__global__ void sg11_sharpness_restore_kernel(
237	    ParamT* param, float* sharpness, const ParamT* backup,
238	    const ParamT* sam_grad, const ParamT* normal_grad, int64_t N
239	) {
240	    const int64_t stride = prim::grid_stride();
241	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
242	        param[i] = backup[i];
243	        float sg = static_cast<float>(sam_grad[i]);
244	        float ng = static_cast<float>(normal_grad[i]);
245	        float diff = sg - ng;
246	        sharpness[i] = diff * diff;
247	    }
248	}
249	
